delta = {
    ("even", "0"): "even",
    ("even", "1"): "odd",
    ("odd", "0"): "odd",
    ("odd", "1"): "even",
}

def run(word):
    state = "even"
    for symbol in word:
        state = delta[(state, symbol)]
    return state

state = "even"
for symbol in "1101":
    state = delta[(state, symbol)]
    print("read", symbol, "-> state", state)

for word in ["", "1", "11", "0110", "10101"]:
    if word.count("1") % 2 == 0:
        expected = "even"
    else:
        expected = "odd"
    print(repr(word), run(word), run(word) == expected)

